import { createHash } from 'node:crypto';
import { z } from 'zod';
import data from './attribution-227-matches.json' with { type: 'json' };

/**
 * The #227 rule's scripted match (owner decision of 2026-11-10, item 1;
 * design `research/admission-227-design.md` §B, §F slice 3): the books of a
 * record that declares none. Generated by `pnpm catalog:attribution-227-matches
 * --write` (`attribution-227-matcher.ts`) and read by the gate
 * (`admission.ts`, `decideOnDeclaredBooks`) when the record's sources are
 * empty. A record the file doesn't list has no match and is held as before.
 *
 * Each match's evidence is one of:
 * - `pcgen`: the record's name, or a `KEY:`, in column 1 of a pinned PCGen
 *   list of the same object family, the book from the file's folder
 *   (`pcgen-books*.json`);
 * - `pcgen-fallback`: for a class feature when no name or `KEY:` is the same,
 *   a line found by its `rule`: a `KEY:` with the same words in another order
 *   (`word-order`), or the PCGen name with its trailing parenthetical dropped
 *   (`without-parenthetical`);
 * - `stored-assessment`: the books its stored Attribution Assessment names
 *   (`requiredNotices`), where its legal record names the PCGen line it was
 *   compared with.
 * A class feature also takes its Foundry classes' declared books. A record is
 * held when only its class association names a book (`association-only`), or
 * when the `KEY:`s with its words in another order belong to lines naming two
 * or more PCGen objects (`ambiguous-word-order`, every such line listed).
 *
 * The file stores each shared record once (`docs/agents/generated-artifacts.md`):
 * each PCGen list's book under `listBooks`, each class's name and books under
 * `classes`, by its key. A match names a PCGen line by its list and line and a
 * class by its key; `readAttribution227Matches` expands them into the matches
 * the gate reads, and `compactAttribution227Matches` is the writer's inverse.
 */
const text = z.string().min(1);
const sha256 = z.string().regex(/^[a-f0-9]{64}$/);
/** A non-empty list, typed as a tuple so an empty one can't type-check. */
const nonEmpty = <T extends z.ZodType>(item: T) =>
  z.tuple([item], item).readonly();
/** A line of a pinned PCGen list, its path under the pin's data directory. */
const pcgenLine = z.strictObject({
  file: z.string().regex(/^(?:[a-z0-9_]+\/)+[A-Za-z0-9_.-]+\.lst$/),
  line: z.number().int().positive(),
});
const pcgenEvidence = z.strictObject({
  kind: z.literal('pcgen'),
  book: text,
  ...pcgenLine.shape,
});
/** How a fallback found its line when no name or `KEY:` is the same. */
export const pcgenFallbackRules = [
  'word-order',
  'without-parenthetical',
] as const;
const pcgenFallbackEvidence = z.strictObject({
  kind: z.literal('pcgen-fallback'),
  rule: z.enum(pcgenFallbackRules),
  book: text,
  ...pcgenLine.shape,
});
/** Two or more PCGen lines, as an ambiguous hold lists them. */
const candidateLines = <T extends z.ZodType>(item: T) =>
  z.tuple([item, item], item).readonly();
const storedEvidence = z.strictObject({
  kind: z.literal('stored-assessment'),
  notices: nonEmpty(text),
  /** The legal batch whose record names the PCGen line. */
  batch: z.string().regex(/^scripts\/catalog\/legal\/[a-z0-9-]+\.json$/),
  comparison: pcgenLine,
});
const classBook = z.strictObject({
  externalKey: text,
  name: text,
  books: nonEmpty(text),
});
const record = {
  externalKey: text,
  /** The record's name and kind when matched: a changed record has no match. */
  name: text,
  kind: text,
};

export const attribution227MatchSchema = z.discriminatedUnion('status', [
  z.strictObject({
    ...record,
    status: z.literal('matched'),
    evidence: nonEmpty(
      z.discriminatedUnion('kind', [
        pcgenEvidence,
        pcgenFallbackEvidence,
        storedEvidence,
      ]),
    ),
    classes: z.array(classBook).readonly(),
  }),
  z.strictObject({
    ...record,
    status: z.literal('held'),
    hold: z.discriminatedUnion('kind', [
      /** Only its Foundry class association names a book. */
      z.strictObject({
        kind: z.literal('association-only'),
        classes: nonEmpty(classBook),
      }),
      /** The KEYs with its words in another order name two or more objects. */
      z.strictObject({
        kind: z.literal('ambiguous-word-order'),
        candidates: candidateLines(
          z.strictObject({ book: text, ...pcgenLine.shape }),
        ),
      }),
    ]),
  }),
]);
export type Attribution227Match = z.infer<typeof attribution227MatchSchema>;
export type MatchedAttribution227 = Extract<
  Attribution227Match,
  { status: 'matched' }
>;
export type HeldAttribution227Match = Extract<
  Attribution227Match,
  { status: 'held' }
>;

const header = {
  version: z.literal(2),
  command: z.literal('pnpm -s catalog:attribution-227-matches --write'),
  binding: z.strictObject({
    /** The Foundry pins the records were imported at (`inventory.ts`, `pins`). */
    upstream: nonEmpty(
      z.strictObject({
        repository: text,
        commit: z.string().regex(/^[a-f0-9]{40}$/),
      }),
    ),
    /** The PCGen pin the lists were read at (`inventory.ts`, `pcgenPin`). */
    pcgen: z.strictObject({
      commit: z.string().regex(/^[a-f0-9]{40}$/),
      directory: text,
    }),
    /** The repository files the matcher read or ran, with their sha256. */
    inputs: z.record(text, sha256),
    /**
     * sha256 of the canonical expanded `matches` array: a hand edit drifts
     * from it.
     */
    matchesSha256: sha256,
  }),
};
/** Matches sorted by key, each key once. */
const sortedByKey = (
  document: { matches: readonly { externalKey: string }[] },
  context: z.RefinementCtx,
) =>
  document.matches.forEach(({ externalKey }, index) => {
    const previous = document.matches[index - 1]?.externalKey;
    if (previous !== undefined && previous >= externalKey)
      context.addIssue({
        code: 'custom',
        path: ['matches', index],
        message: 'Matches must be sorted by key, each key once.',
      });
  });

/** The matches the gate reads, each record expanded. */
export const attribution227MatchesSchema = z
  .strictObject({
    ...header,
    matches: z.array(attribution227MatchSchema).readonly(),
  })
  .superRefine(sortedByKey);
export type Attribution227Matches = z.infer<typeof attribution227MatchesSchema>;

/** A PCGen line by its list and line: the list's book is in `listBooks`. */
const pcgenReference = z.strictObject({
  kind: z.literal('pcgen'),
  ...pcgenLine.shape,
});
const pcgenFallbackReference = z.strictObject({
  kind: z.literal('pcgen-fallback'),
  rule: z.enum(pcgenFallbackRules),
  ...pcgenLine.shape,
});
/** A class by its key in `classes`. */
const classReference = text;
const storedMatchSchema = z.discriminatedUnion('status', [
  z.strictObject({
    ...record,
    status: z.literal('matched'),
    evidence: nonEmpty(
      z.discriminatedUnion('kind', [
        pcgenReference,
        pcgenFallbackReference,
        storedEvidence,
      ]),
    ),
    classes: z.array(classReference).readonly(),
  }),
  z.strictObject({
    ...record,
    status: z.literal('held'),
    hold: z.discriminatedUnion('kind', [
      z.strictObject({
        kind: z.literal('association-only'),
        classes: nonEmpty(classReference),
      }),
      z.strictObject({
        kind: z.literal('ambiguous-word-order'),
        candidates: candidateLines(pcgenLine),
      }),
    ]),
  }),
]);

/** The file as stored: each list's book and each class once, by key. */
export const attribution227MatchesFileSchema = z
  .strictObject({
    ...header,
    /** Each matched PCGen list's book (its folder's crosswalk code). */
    listBooks: z.record(pcgenLine.shape.file, text),
    /** Each matched class's name and declared books, by its key. */
    classes: z.record(
      text,
      z.strictObject({ name: text, books: nonEmpty(text) }),
    ),
    matches: z.array(storedMatchSchema).readonly(),
  })
  .superRefine(sortedByKey);
export type Attribution227MatchesFile = z.infer<
  typeof attribution227MatchesFileSchema
>;
type StoredMatch = Attribution227MatchesFile['matches'][number];
type ClassBook = z.infer<typeof classBook>;
type PcgenLineOfBook = { book: string; file: string; line: number };

/**
 * The file's matches expanded: each PCGen line with its list's book, each
 * class with its name and books. Fails on a reference the file doesn't
 * resolve and on an entry no match names.
 */
export function readAttribution227Matches(
  data: unknown,
): Attribution227Matches {
  const { listBooks, classes, matches, ...header } =
    attribution227MatchesFileSchema.parse(data);
  const usedLists = new Set<string>();
  const usedClasses = new Set<string>();
  const bookOf = (file: string) => {
    const book = listBooks[file];
    if (book === undefined)
      throw new Error(`No book for PCGen list ${file} in listBooks.`);
    usedLists.add(file);
    return book;
  };
  const line = ({ file, line }: { file: string; line: number }) => ({
    book: bookOf(file),
    file,
    line,
  });
  const classOf = (externalKey: string): ClassBook => {
    const found = classes[externalKey];
    if (!found) throw new Error(`No class ${externalKey} in classes.`);
    usedClasses.add(externalKey);
    return { externalKey, ...found };
  };
  const classList = (keys: readonly [string, ...string[]]) =>
    [classOf(keys[0]), ...keys.slice(1).map(classOf)] as const;
  const expand = (match: StoredMatch): Attribution227Match => {
    const base = {
      externalKey: match.externalKey,
      name: match.name,
      kind: match.kind,
    };
    if (match.status === 'matched') {
      const item = (evidence: (typeof match.evidence)[number]) =>
        evidence.kind === 'stored-assessment'
          ? evidence
          : { ...evidence, book: bookOf(evidence.file) };
      return {
        ...base,
        status: 'matched',
        evidence: [
          item(match.evidence[0]),
          ...match.evidence.slice(1).map(item),
        ],
        classes: match.classes.map(classOf),
      };
    }
    const { hold } = match;
    return {
      ...base,
      status: 'held',
      hold:
        hold.kind === 'association-only'
          ? { kind: hold.kind, classes: classList(hold.classes) }
          : {
              kind: hold.kind,
              candidates: [
                line(hold.candidates[0]),
                line(hold.candidates[1]),
                ...hold.candidates.slice(2).map(line),
              ],
            },
    };
  };
  const expanded = matches.map(expand);
  const unused = [
    ...Object.keys(listBooks).filter((file) => !usedLists.has(file)),
    ...Object.keys(classes).filter((key) => !usedClasses.has(key)),
  ];
  if (unused.length) throw new Error(`No match names ${unused.join(', ')}.`);
  return attribution227MatchesSchema.parse({ ...header, matches: expanded });
}

/**
 * The file form of a matches document (`readAttribution227Matches`'s
 * inverse): each list's book and each class once, sorted by key. Fails when
 * two matches give a list different books or a class different records.
 */
export function compactAttribution227Matches(
  document: Attribution227Matches,
): Attribution227MatchesFile {
  const { matches, ...header } = document;
  const listBooks = new Map<string, string>();
  const classes = new Map<string, { name: string; books: readonly string[] }>();
  const line = ({ book, file, line }: PcgenLineOfBook) => {
    const known = listBooks.get(file);
    if (known !== undefined && known !== book)
      throw new Error(`PCGen list ${file} has two books: ${known}, ${book}.`);
    listBooks.set(file, book);
    return { file, line };
  };
  const classKey = ({ externalKey, name, books }: ClassBook) => {
    const known = classes.get(externalKey);
    if (known && JSON.stringify(known) !== JSON.stringify({ name, books }))
      throw new Error(`Class ${externalKey} has two records.`);
    classes.set(externalKey, { name, books });
    return externalKey;
  };
  const compact = (match: Attribution227Match): unknown => {
    const base = {
      externalKey: match.externalKey,
      name: match.name,
      kind: match.kind,
    };
    if (match.status === 'matched')
      return {
        ...base,
        status: 'matched',
        evidence: match.evidence.map((item) => {
          if (item.kind === 'stored-assessment') return item;
          const { book, ...reference } = item;
          return { ...reference, ...line({ book, ...reference }) };
        }),
        classes: match.classes.map(classKey),
      };
    const { hold } = match;
    return {
      ...base,
      status: 'held',
      hold:
        hold.kind === 'association-only'
          ? { kind: hold.kind, classes: hold.classes.map(classKey) }
          : { kind: hold.kind, candidates: hold.candidates.map(line) },
    };
  };
  const stored = matches.map(compact);
  const sorted = <T>(map: ReadonlyMap<string, T>) =>
    Object.fromEntries(
      [...map].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    );
  return attribution227MatchesFileSchema.parse({
    ...header,
    listBooks: sorted(listBooks),
    classes: sorted(classes),
    matches: stored,
  });
}

export const committedAttribution227Matches = readAttribution227Matches(data);

/** The canonical bytes' hash of a matches array (`binding.matchesSha256`). */
export const matchesSha256 = (matches: readonly Attribution227Match[]) =>
  createHash('sha256').update(JSON.stringify(matches)).digest('hex');

/** A match's books: its evidence's, then its classes' declared books, sorted. */
export function matchedBooks(
  match: MatchedAttribution227,
): readonly [string, ...string[]] {
  const [first, ...rest] = [
    ...new Set([
      ...match.evidence.flatMap((item) =>
        item.kind === 'stored-assessment' ? item.notices : [item.book],
      ),
      ...match.classes.flatMap(({ books }) => books),
    ]),
  ].sort();
  // Its evidence is non-empty, and each item names a book.
  if (first === undefined) throw new Error('A match names no book.');
  return [first, ...rest];
}

/**
 * The gate's lookup: a record's match, `stale` when the file lists its key
 * under another name or kind (the import changed since the match), or
 * `undefined` when it lists none.
 */
export function attribution227MatchLookup(
  document: Pick<Attribution227Matches, 'matches'>,
) {
  const byKey = new Map(
    document.matches.map((match) => [match.externalKey, match]),
  );
  return (entry: {
    externalKey: string;
    name: string;
    detail: { kind: string };
  }):
    | Attribution227Match
    | { status: 'stale'; match: Attribution227Match }
    | undefined => {
    const match = byKey.get(entry.externalKey);
    if (!match) return undefined;
    return match.name === entry.name && match.kind === entry.detail.kind
      ? match
      : { status: 'stale', match };
  };
}
